interface MockResponseType {
  status: number;
  request?: any;
  response: any;
  params?: any;
}

interface MockHistoryEntry {
  id: string;
  timestamp: number;
  method: string;
  url: string;
  requestBody?: any;
  requestHeaders?: Record<string, string>;
  status: number;
  statusText: string;
  responseBody: any;
  responseHeaders?: Record<string, string>;
  duration: number; // ms
}

export class CustomMockService {
  private static getMockMapping = new Map<string, MockResponseType>();
  private static postMockMapping = new Map<string, MockResponseType>();
  private static patchMockMapping = new Map<string, MockResponseType>();
  private static deleteMockMapping = new Map<string, MockResponseType>();
  private static history: MockHistoryEntry[] = [];
  private static isDevRun = true;

  private static getStatusText(statusCode: number): string {
    const statusMap: Record<number, string> = {
      200: "OK",
      201: "Created",
      204: "No Content",

      301: "Moved Permanently",
      302: "Found",
      304: "Not Modified",

      400: "Bad Request",
      401: "Unauthorized",
      403: "Forbidden",
      404: "Not Found",
      409: "Conflict",
      422: "Unprocessable Entity",

      500: "Internal Server Error",
      502: "Bad Gateway",
      503: "Service Unavailable",
    };

    return statusMap[statusCode] || "Unknown";
  }

  static print() {
    console.log(this.getMockMapping);
  }

  static getHistory(): MockHistoryEntry[] {
    return [...this.history];
  }

  static clearHistory(): void {
    this.history = [];
  }

  private static addToHistory(
    method: string,
    url: string,
    requestBody: any,
    mockData: MockResponseType,
    startTime: number
  ): void {
    const entry: MockHistoryEntry = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      method,
      url,
      requestBody,
      status: mockData.status,
      statusText: this.getStatusText(mockData.status),
      responseBody: mockData.response,
      duration: Date.now() - startTime,
    };

    this.history.unshift(entry);

    if (this.history.length > 100) {
      this.history = this.history.slice(0, 100);
    }
  }

  static run(isDevRun: boolean = true) {
    CustomMockService.isDevRun = isDevRun;

    if (!CustomMockService.validate()) {
      console.log("MockServer: 현재 환경에서는 실행되지 않습니다");
      return;
    }

    this.patchFetch();
    this.patchXHR();
    console.log("CustomMockService is Running");
    console.log("등록된 Mock 데이터:", {
      GET: Array.from(this.getMockMapping.keys()),
      POST: Array.from(this.postMockMapping.keys()),
      PATCH: Array.from(this.patchMockMapping.keys()),
      DELETE: Array.from(this.deleteMockMapping.keys()),
    });
  }

  private static validate(): boolean {
    if (typeof window === "undefined") {
      console.log("MockServer 검증 실패: window가 정의되지 않음");
      return false;
    }

    if (this.isDevRun) {
      const result = process.env.NODE_ENV === "development";
      console.log("검증 결과:", result);
      return result;
    }
    return true;
  }

  static get({
    endPoint,
    status = 200,
    params = null,
    response,
  }: {
    endPoint: string;
    status?: number;
    params?: any;
    response: any;
  }) {
    this.getMockMapping.set(`${endPoint}`, {
      status,
      request: params,
      response,
    });
  }

  static post({
    endPoint,
    status = 200,
    request = null,
    response,
  }: {
    endPoint: string;
    status?: number;
    request?: any;
    response: any;
  }) {
    this.postMockMapping.set(`${endPoint}`, { status, request, response });
  }

  static patch({
    endPoint,
    status = 200,
    request = null,
    response,
  }: {
    endPoint: string;
    status?: number;
    request?: any;
    response: any;
  }) {
    this.patchMockMapping.set(`${endPoint}`, { status, request, response });
  }

  static delete({
    endPoint,
    status = 200,
    request = null,
    response,
  }: {
    endPoint: string;
    status?: number;
    request?: any;
    response?: any;
  }) {
    this.deleteMockMapping.set(`${endPoint}`, { status, request, response });
  }

  static patchXHR() {
    const OriginalXHR = window.XMLHttpRequest;
    (window.XMLHttpRequest as any) = function () {
      const xhr = new OriginalXHR();

      let httpMethod: string;
      let requestUrl: string;
      let urlParams: URLSearchParams;

      const originalOpen = xhr.open;
      xhr.open = function (
        m: string,
        u: string,
        async?: boolean,
        user?: string,
        password?: string
      ) {
        httpMethod = m;
        requestUrl = u;
        urlParams = new URLSearchParams(new URL(u).search);

        return originalOpen.call(this, m, u, async || true, user, password);
      };

      const originalSend = xhr.send;
      xhr.send = function (body?: any) {
        const startTime = Date.now();
        const requestBody = body;
        const mockData = CustomMockService.findMockData(httpMethod, requestUrl);

        if (mockData) {
          console.log("Mock 데이터 존재 O -> 가짜 응답 반환", mockData);

          CustomMockService.addToHistory(
            httpMethod,
            requestUrl,
            requestBody,
            mockData,
            startTime
          );

          CustomMockService.returnMockResponse(xhr, mockData);
          return;
        }

        console.log("Mock 데이터 X -> 실제 요청 진행");
        return originalSend.call(this, body);
      };

      return xhr;
    };
  }

  static patchFetch() {
    const originalFetch = window.fetch;

    window.fetch = async function (
      input: RequestInfo | URL,
      init?: RequestInit
    ): Promise<Response> {
      const url =
        typeof input === "string"
          ? input
          : input instanceof URL
          ? input.href
          : input.url;
      const method = init?.method?.toUpperCase() || "GET";

      console.log(`Fetch: ${method} ${url}`);

      let mockData;
      switch (method) {
        case "GET":
          mockData = CustomMockService.getMockMapping.get(url);
          break;
        case "POST":
          mockData = CustomMockService.postMockMapping.get(url);
          break;
        case "PATCH":
          mockData = CustomMockService.patchMockMapping.get(url);
          break;
        case "DELETE":
          mockData = CustomMockService.deleteMockMapping.get(url);
          break;
      }

      if (mockData) {
        console.log("Mock 데이터 존재 O -> 가짜 응답 반환", mockData);

        return new Response(JSON.stringify(mockData.response), {
          status: 200,
          statusText: "OK",
          headers: {
            "Content-Type": "application/json",
          },
        });
      }

      console.log("Mock 데이터 X -> 실제 요청 진행");
      return originalFetch.call(window, input, init);
    };
  }

  private static findMockData(httpMethod: string, requestUrl: string) {
    let mapping;

    switch (httpMethod) {
      case "GET":
        mapping = CustomMockService.getMockMapping.get(requestUrl);
        break;
      case "POST":
        mapping = CustomMockService.postMockMapping.get(requestUrl);
        break;
      case "PATCH":
        mapping = CustomMockService.patchMockMapping.get(requestUrl);
        break;
      case "DELETE":
        mapping = CustomMockService.deleteMockMapping.get(requestUrl);
        break;
    }
    return mapping;
  }

  private static returnMockResponse = (xhr: XMLHttpRequest, mockData: any) => {
    setTimeout(() => {
      Object.defineProperty(xhr, "readyState", {
        value: 4,
        configurable: true,
      });
      Object.defineProperty(xhr, "status", {
        value: mockData.status,
        configurable: true,
      });
      Object.defineProperty(xhr, "statusText", {
        value: CustomMockService.getStatusText(mockData.status),
        configurable: true,
      });
      Object.defineProperty(xhr, "responseText", {
        value: JSON.stringify(mockData.response),
        configurable: true,
      });
      Object.defineProperty(xhr, "response", {
        value: JSON.stringify(mockData.response),
        configurable: true,
      });

      const readystateEvent = new Event("readystatechange");
      if (xhr.onreadystatechange)
        xhr.onreadystatechange.call(xhr, readystateEvent);

      const loadEvent = new ProgressEvent("load");
      if (xhr.onload) xhr.onload.call(xhr, loadEvent);

      const loadendEvent = new ProgressEvent("loadend");
      if (xhr.onloadend) xhr.onloadend.call(xhr, loadendEvent);
    }, 50);
  };
}
